argv:
$ErrorActionPreference='Stop'
$p='E:\work\video2-r25-local-run\focused2.log'
$lines=[IO.File]::ReadAllLines($p,[Text.Encoding]::Unicode)
$out=@()
for($i=0;$i -lt $lines.Length;$i++){
  if($lines[$i] -match '(?i)not ok|# fail|AssertionError|Error:|failed'){
    $a=[Math]::Max(0,$i-3);$b=[Math]::Min($lines.Length-1,$i+8)
    for($j=$a;$j -le $b;$j++){ $out += ('{0}:{1}' -f ($j+1),$lines[$j]) }
    $out += '---'
  }
}
$out | Select-Object -Last 120
